        ) : ServiceException() {
        override val message
            get() = ""
    }
    
    /**
     * The API, or the way to it.
     */
    class Api(
        
        val v1: kotlin.String
        ) : ServiceException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The directories involved.
     */
